package com.example.voxara.core.scene

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import kotlin.math.PI
import kotlin.math.abs
import kotlin.math.sin

/**
 * PYTHON <-> KOTLIN PARITY. The model was trained on features computed by voxfeat.py; the watch
 * computes them with [SceneFeatureExtractor]. Both run on the same deterministic signal and must
 * agree to well under anything the model could notice. The reference vectors are generated by
 * make_reference.py (see [SceneFeaturesReference]).
 */
class SceneFeaturesParityTest {

    /** Same as voxfeat.reference_signal(): two tones, a slow wobble and LCG noise, cast to float. */
    private fun referenceSignal(n: Int, seed: Long = SceneFeaturesReference.SEED): FloatArray {
        var state = seed
        return FloatArray(n) { i ->
            state = (state * 1103515245L + 12345L) % 2147483648L
            val u = state / 2147483648.0 * 2.0 - 1.0
            val t = i.toDouble() / SceneFeatures.SAMPLE_RATE
            val v = 0.30 * sin(2.0 * PI * 440.0 * t) * (0.6 + 0.4 * sin(2.0 * PI * 3.0 * t)) +
                0.10 * sin(2.0 * PI * 3150.0 * t + 0.5) +
                0.05 * u
            v.toFloat()
        }
    }

    private fun assertVectorsMatch(expected: Array<DoubleArray>, actual: List<DoubleArray>) {
        assertEquals(expected.size, actual.size)
        expected.zip(actual).forEachIndexed { v, (e, a) ->
            assertEquals(SceneFeatures.COUNT, a.size)
            for (i in e.indices) {
                assertTrue(
                    "vector $v feature $i: python ${e[i]} kotlin ${a[i]}",
                    abs(e[i] - a[i]) <= 1e-7 * maxOf(1.0, abs(e[i])),
                )
            }
        }
    }

    @Test
    fun `the reference fixture belongs to this feature version`() {
        assertEquals(SceneFeatures.VERSION, SceneFeaturesReference.FEATURE_VERSION)
        assertEquals(SceneFeatures.VERSION, SceneModelWeights.FEATURE_VERSION)
    }

    @Test
    fun `kotlin features equal the python reference, fed in one piece`() {
        val x = referenceSignal(SceneFeaturesReference.SAMPLES)
        val ex = SceneFeatureExtractor()
        ex.push(x)
        assertVectorsMatch(SceneFeaturesReference.VECTORS, ex.takeVectors())
    }

    @Test
    fun `chunking does not change anything - 100 ms reads, odd sizes, 250 ms bursts`() {
        val x = referenceSignal(SceneFeaturesReference.SAMPLES)
        for (chunk in listOf(4_800, 1_000, 777, 12_000)) {
            val ex = SceneFeatureExtractor()
            val out = ArrayList<DoubleArray>()
            var i = 0
            while (i < x.size) {
                val end = minOf(i + chunk, x.size)
                ex.push(x, i, end)
                out += ex.takeVectors()
                i = end
            }
            assertVectorsMatch(SceneFeaturesReference.VECTORS, out)
        }
    }

    @Test
    fun `a partial vector is held back and reset drops it`() {
        val ex = SceneFeatureExtractor()
        ex.push(FloatArray(SceneFeatures.SAMPLES_PER_VECTOR - 1) { 0.1f })
        assertTrue(ex.takeVectors().isEmpty())
        ex.reset()
        ex.push(FloatArray(1) { 0.1f })
        assertTrue("reset must drop the partial vector", ex.takeVectors().isEmpty())
    }

    @Test
    fun `features are gain-invariant apart from the floor`() {
        val x = referenceSignal(SceneFeatures.SAMPLES_PER_VECTOR)
        val a = SceneFeatureExtractor().apply { push(x) }.takeVectors().single()
        val quieter = FloatArray(x.size) { x[it] * 0.01f }
        val b = SceneFeatureExtractor().apply { push(quieter) }.takeVectors().single()
        for (i in a.indices) assertEquals("feature $i", a[i], b[i], 1e-3)
    }

    @Test
    fun `the FFT matches a direct DFT`() {
        val n = 64
        val x = DoubleArray(n) { sin(it * 0.37) + 0.25 * sin(it * 2.1 + 1.0) }
        val got = DoubleArray(n / 2 + 1)
        RealFft(n).powerSpectrum(x.copyOf(), got)
        for (k in 0..n / 2) {
            var re = 0.0
            var im = 0.0
            for (t in 0 until n) {
                re += x[t] * kotlin.math.cos(2 * PI * k * t / n)
                im -= x[t] * sin(2 * PI * k * t / n)
            }
            assertEquals("bin $k", re * re + im * im, got[k], 1e-9)
        }
    }
}
